# Implementasi Simulator Bucketing Spark SQL: Menghilangkan Shuffle pada Join Berulang
class BucketedTableSimulator:
    def __init__(self, table_name, num_buckets=4, bucket_col='user_id'):
        self.table_name = table_name
        self.num_buckets = num_buckets
        self.bucket_col = bucket_col
        self.buckets = {i: [] for i in range(num_buckets)}

    def write_bucketed_data(self, records):
        for r in records:
            val = r[self.bucket_col]
            b_idx = hash(val) % self.num_buckets
            self.buckets[b_idx].append(r)

        # Pra-urutkan setiap bucket fisik
        for b_idx in self.buckets:
            self.buckets[b_idx].sort(key=lambda x: x[self.bucket_col])

    @staticmethod
    def bucketed_sort_merge_join(tbl_a, tbl_b):
        # Jika kedua tabel memiliki jumlah bucket dan kunci yang sama, shuffle dihilangkan!
        if tbl_a.num_buckets != tbl_b.num_buckets:
            return {'shuffle_eliminated': False, 'matches': 0}

        matched_pairs = []
        # Eksekusi join lokal per-bucket secara independen tanpa network transfer!
        for b_idx in range(tbl_a.num_buckets):
            list_a = tbl_a.buckets[b_idx]
            list_b = tbl_b.buckets[b_idx]
            for ra in list_a:
                for rb in list_b:
                    if ra[tbl_a.bucket_col] == rb[tbl_b.bucket_col]:
                        matched_pairs.append((ra, rb))

        return {'shuffle_eliminated': True, 'matches': len(matched_pairs)}

# Inisialisasi 2 tabel dengan 4 bucket pada kolom 'user_id'
orders_tbl = BucketedTableSimulator('orders', num_buckets=4, bucket_col='user_id')
users_tbl = BucketedTableSimulator('users', num_buckets=4, bucket_col='user_id')

orders_tbl.write_bucketed_data([{'user_id': 101, 'amount': 250}, {'user_id': 102, 'amount': 150}, {'user_id': 103, 'amount': 400}])
users_tbl.write_bucketed_data([{'user_id': 101, 'name': 'Alice'}, {'user_id': 102, 'name': 'Bob'}, {'user_id': 103, 'name': 'Charlie'}])

join_res = BucketedTableSimulator.bucketed_sort_merge_join(orders_tbl, users_tbl)

print('Evaluasi Optimasi Bucketing pada Spark SQL:')
print(f'  Jumlah Bucket Kedua Tabel : 4 Bucket (Selaras)')
print(f'  Peniadaan Tahapan Shuffle : {join_res["shuffle_eliminated"]} (Zero Network Transfer!)')
print(f'  Total Pasangan Cocok     : {join_res["matches"]}')
print('Kesimpulan: Bucketing memindahkan biaya shuffle saat write sehingga kueri join berjalan instan.')
